sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;

    var inputs = {};
    inputs['prompt'] = body.prompt;
    inputs['model'] = body.model;
    inputs['file_ids'] = body.file_ids;

    try {
        var result = sn_fd.FlowAPI.getRunner()
            .action('x_1815796_itsmgr_0.call_bot_with_rag')
            .inForeground()
            .withInputs(inputs)
            .run();

        var outputs = result.getOutputs();
        gs.info("Action Outputs Debug: " + JSON.stringify(outputs));
        var success = outputs.success;
        var answer = outputs.answer;
        var error_message = outputs.error_message;

        gs.info("Action Outputs Debug -> Success: " + success + " | Answer: " + answer + " | Error: " + error_message);

        if (success == 'true' || success === true) {
            response.setBody({
                "status": "success",
                "ai_response": answer
            });
        } else {
            response.setStatus(500);
            response.setBody({
                "status": "failure",
                "message": error_message
            });
        }
    } catch (ex) {
        response.setStatus(500);
        response.setBody({
            "status": "failure",
            "message": ex.message
        });
    }
})(request, response);
